/**
 * @file Widget Recipe — Glass Void
 * @id widget.glass.void
 * @kind widget
 * @layer recipes
 *
 * Props → Tailwind v4 utilities (structural) + variant keys (visual).
 * Structural: flex, padding, border — standard TW.
 * Visual: v-s (surface), v-z (depth), v-l (layers) — generated by pipeline.
 *
 * All color references use token TW utilities (border-border-soft, text-text-link).
 * Zero hardcoded oklch values.
 */

import { cn } from "$lib/design/utils/cn.js";
import { registerRecipe } from "../../index.js";
import type { DsSurfaceProps } from "../../types.js";
import { radiusClass } from "../../utils.js";

